// Command generate-authz-vocabulary publishes the authorization vocabulary
// from internal/authz, and gates it.
//
// It writes two artefacts. Do not edit them by hand:
//
//	docs/vocabularies/authorization.json                  the machine-readable set
//	docs/src/content/docs/authorization-vocabulary.md     the reference an operator reads
//
// The set is the actions, the types, the relations and the permitted tuple
// shapes, all read from the code that enforces them.
//
// A committed row the code does not declare fails the run unless
// -allow-removals is set. With -check it writes nothing and fails when a
// committed artefact differs from the generated one.
//
// Run via: make generate-authz-vocabulary, gated by make authz-vocabulary-check.
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"

	"github.com/prusa3d/prusa-connect/internal/authz"
	"github.com/prusa3d/prusa-connect/internal/codegen"
)

const (
	defaultCataloguePath = "docs/vocabularies/authorization.json"
	defaultReferencePath = "docs/src/content/docs/authorization-vocabulary.md"

	// generatedNotice is the first thing in both artefacts.
	generatedNotice = "Generated by 'make generate-authz-vocabulary' from the closed sets this " +
		"build links. Do not edit: change the vocabulary in Go and regenerate."
)

// vocabulary is the whole published set. Both artefacts are generated from
// one read of it.
type vocabulary struct {
	Actions   []authz.ActionDoc
	Types     []authz.TypeDoc
	Relations []authz.RelationDoc
	Shapes    []authz.ShapeDoc
}

func current() vocabulary {
	return vocabulary{
		Actions:   authz.ActionDocs(),
		Types:     authz.TypeDocs(),
		Relations: authz.RelationDocs(),
		Shapes:    authz.Shapes(),
	}
}

type options struct {
	cataloguePath string
	referencePath string
	check         bool
	allowRemovals bool
}

func main() {
	opts := options{}

	flag.StringVar(&opts.cataloguePath, "catalogue", defaultCataloguePath,
		"path of the machine-readable authorization vocabulary")
	flag.StringVar(&opts.referencePath, "reference", defaultReferencePath,
		"path of the published authorization reference")
	flag.BoolVar(&opts.check, "check", false,
		"compare the committed artefacts against the generated ones and write nothing")
	flag.BoolVar(&opts.allowRemovals, "allow-removals", false,
		"let an action, type or relation disappear. A written grant still names it: for a "+
			"deliberate retirement in a breaking release only")
	flag.Parse()

	if err := run(current(), opts); err != nil {
		fmt.Fprintf(os.Stderr, "generate-authz-vocabulary: %v\n", err)
		os.Exit(1)
	}
}

func run(set vocabulary, opts options) error {
	committed, err := codegen.ReadCatalogue[catalogueFile](opts.cataloguePath)
	if err != nil {
		return err
	}

	if err = checkDescribed(set); err != nil {
		return err
	}

	if err = checkUnknown(committed, set, opts.allowRemovals); err != nil {
		return err
	}

	// checkMissing runs only under -check. On a write it would refuse the
	// command that adds the missing entry.
	if opts.check {
		if err = checkMissing(committed, set); err != nil {
			return err
		}
	}

	machine, err := renderCatalogue(set)
	if err != nil {
		return err
	}

	human := renderReference(set)

	if opts.check {
		return errors.Join(
			compareFile(opts.cataloguePath, machine),
			compareFile(opts.referencePath, human),
		)
	}

	if err = codegen.WriteFile(opts.cataloguePath, machine); err != nil {
		return err
	}

	if err = codegen.WriteFile(opts.referencePath, human); err != nil {
		return err
	}

	fmt.Fprintf(os.Stderr, "OK authorization vocabulary: %s (%d actions, %d types, %d relations, %d shapes)\n",
		opts.cataloguePath, len(set.Actions), len(set.Types), len(set.Relations), len(set.Shapes))
	fmt.Fprintf(os.Stderr, "OK authorization reference: %s\n", opts.referencePath)

	return nil
}
